const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const key=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const today=key(new Date()), parse=k=>new Date(k+'T12:00:00'), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initial={theme:'playful',color:'rose',icon:'cat',showFocus:true,habits:[{id:'water',name:'Water',icon:'♧',target:4,badge:'💧',monthly:true},{id:'food',name:'Food',icon:'◒',target:3,badge:'🍊',monthly:true},{id:'skin',name:'Skincare',icon:'✧',target:1,badge:'✨',monthly:true}],days:{},weeks:{},timer:{running:false,base:0,start:null,goal:20},sessions:[]};
let state;try{state=JSON.parse(localStorage.getItem('little-days-v1'))||initial}catch{state=initial}let page='today',selected=today,diaryView='week',diaryDate=today,zoom=innerWidth<580?.46:.72,activeStamp=null;
function save(){try{localStorage.setItem('little-days-v1',JSON.stringify(state))}catch{toast('Storage is full. Please export a backup.')}}
function day(k=selected){if(!state.days[k])state.days[k]={habits:JSON.parse(JSON.stringify(state.habits)),ticks:{},text:'',badges:[]};return state.days[k]}
function habitsFor(k=selected){const d=day(k);if(k===today){d.habits=JSON.parse(JSON.stringify(state.habits))}return d.habits||state.habits}
function ordinal(n){return n+([11,12,13].includes(n%100)?'th':({1:'st',2:'nd',3:'rd'}[n%10]||'th'))}
function fullDate(k){const d=parse(k);return `${ordinal(d.getDate())} ${d.toLocaleDateString('en-GB',{month:'long',year:'numeric'})}`}
function shift(k,n){const d=parse(k);d.setDate(d.getDate()+n);return key(d)}
function weekStart(k){let d=parse(k);d.setDate(d.getDate()-((d.getDay()+6)%7));return key(d)}
function applyStyle(){document.body.classList.toggle('elegant',state.theme==='elegant');if(state.theme==='playful'&&state.color==='sage'){document.body.style.setProperty('--accent','#69795e');document.body.style.setProperty('--soft','#e5ebd9')}else{document.body.style.removeProperty('--accent');document.body.style.removeProperty('--soft')}}
function cat(){if(state.icon==='flower')return '<span style="font-size:75px;color:var(--accent)">✿</span>';if(state.icon==='moon')return '<span style="font-size:75px;color:var(--accent)">☾</span>';return `<svg viewBox="0 0 160 100" aria-label="A smiling hand-drawn cat" role="img"><path d="M31 35 28 8Q29 4 34 7L58 21Q84 15 105 21L130 5Q136 3 134 14L133 39Q148 75 113 84Q71 96 39 80Q18 69 31 35Z" fill="#fffaf4" stroke="#51453f" stroke-width="3.5" stroke-linejoin="round"/><path d="m25 52-14-3m16 12-14 5m125-19 13-5m-12 15 14 2" fill="none" stroke="#51453f" stroke-width="3" stroke-linecap="round"/><ellipse cx="51" cy="63" rx="10" ry="7" fill="#efaf98"/><ellipse cx="117" cy="59" rx="10" ry="7" fill="#efaf98"/><circle cx="62" cy="46" r="2.7" fill="#51453f"/><circle cx="106" cy="43" r="2.7" fill="#51453f"/><path d="m78 60 6 5 7-7" fill="none" stroke="#51453f" stroke-width="2.7" stroke-linecap="round"/></svg>`}
function character(label=true){return `<div class="character"><button onclick="iconDialog()" aria-label="Choose your character">${cat()}<span class="hero-star">✧</span></button>${label?'<small>YOUR LITTLE COMPANION</small>':''}</div>`}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimeout);window.toastTimeout=setTimeout(()=>$('#toast').classList.remove('show'),2800)}
function modal(html){$('#modalBody').innerHTML=html;$('#modal').showModal()}function closeModal(){$('#modal').close()}
$('.close').onclick=closeModal;$('#modal').onclick=e=>{if(e.target===$('#modal'))closeModal()};
function render(){applyStyle();$$('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#content').innerHTML=page==='today'?renderToday():page==='timer'?renderTimer():renderDiary();if(page==='diary'&&diaryView==='week')bindStamps();updateClock()}
function navigate(p){page=p;location.hash=p;render();window.scrollTo(0,0)}$$('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));
function renderToday(){const d=day(),habits=habitsFor(),count=habits.reduce((n,h)=>n+Math.min(d.ticks[h.id]||0,h.target),0),isToday=selected===today;return `<section class="hero"><div><div class="eyebrow">${isToday?'A FRESH LITTLE PAGE':'A PAGE FROM YOUR DAYS'}</div><h1>${isToday?'Hello, you.':'Your little day.'}</h1><p class="subtitle">A moment for yourself. A few little things.</p><div class="date-controls"><button class="arrow" onclick="changeDay(-1)" aria-label="Previous day">‹</button><span>${parse(selected).toLocaleDateString('en-GB',{weekday:'long'})}, ${fullDate(selected)}</span><button class="arrow" onclick="changeDay(1)" aria-label="Next day">›</button></div></div>${character()}</section><div class="grid"><section class="card"><div class="card-head"><h2>Little rituals</h2><button class="text-button" onclick="editHabits()">Edit habits ↗</button></div><div class="habit-list">${habits.map(h=>`<div class="habit"><span class="habit-icon">${esc(h.icon)}</span><div><div class="habit-name">${esc(h.name)}</div><div class="habit-hint">${h.target===1?'A little care for you':`${d.ticks[h.id]||0} of ${h.target} little moments`}</div></div><div class="ticks">${Array.from({length:h.target},(_,i)=>`<button class="tick ${(d.ticks[h.id]||0)>i?'checked':''}" aria-label="${esc(h.name)}: ${i+1} of ${h.target}" aria-pressed="${(d.ticks[h.id]||0)>i}" onclick="tick('${h.id}',${i+1})">${(d.ticks[h.id]||0)>i?'✓':''}</button>`).join('')}</div></div>`).join('')}</div><p class="gentle-note"><span>♡</span> Every little bit counts. There’s no catching up to do.</p></section><div class="right-stack">${state.showFocus?`<section class="card focus-card"><div class="eyebrow">MAKE A LITTLE ROOM</div><h2>Time for a little focus?</h2><p>One thing at a time.<br>Pick a moment and settle in.</p><div class="duration-options">${[20,40,60].map(n=>`<button class="pill" onclick="startFocus(${n})">${n} min</button>`).join('')}</div><div class="focus-bottom"><span>${todayMinutes()} minutes for yourself today</span><button onclick="navigate('timer')">${state.timer.running?'Timer running ↗':'Open timer ↗'}</button></div></section>`:''}<section class="card journal-card"><div class="eyebrow">A NOTE TO REMEMBER</div><h2>How’s your day unfolding?</h2><textarea id="quickEntry" aria-label="Today's diary entry" placeholder="A small joy, a passing thought, anything at all…" oninput="saveQuick(this.value)">${esc(d.text)}</textarea><div class="journal-bottom"><span id="saveStatus">Saved just for you</span><button onclick="openEntry('${selected}')">A little more space ↗</button></div></section></div></div><div class="daily-strip"><span class="flower">✿</span><div><strong>${count?'You made a little space for yourself.':'Today doesn’t have to be a big day.'}</strong><p>${count?`${count} little moments recorded. All at your own pace.`:'Start wherever you are. There’s room for that here.'}</p></div><button onclick="diaryDate=selected;navigate('diary')">Your week ↗</button></div>`}
function changeDay(n){selected=shift(selected,n);render()}
function tick(id,n){const d=day();d.ticks[id]=d.ticks[id]===n?n-1:n;save();render()}
function saveQuick(v){day().text=v;save();$('#saveStatus').textContent='Saved on this device'}
function openEntry(k){modal(`<div class="eyebrow">YOUR DIARY</div><h2>${fullDate(k)}</h2><textarea class="full" id="entryText" placeholder="Make yourself at home on this page…">${esc(day(k).text)}</textarea><div class="dialog-actions"><button class="primary" id="saveEntry">Save entry</button></div>`);$('#saveEntry').onclick=()=>{day(k).text=$('#entryText').value;save();closeModal();render();toast('Your words are saved')}}
function editHabits(){if(selected!==today){toast('Habits can be edited from today’s page.');return}modal(`<h2>Your little rituals</h2><p class="subtitle">Changes apply from today. Earlier days stay as they were.</p>${state.habits.map(h=>`<div class="setting-row"><span>${esc(h.name)} · ${h.target} ${h.target===1?'tick':'ticks'}</span><button class="text-button" onclick="habitForm('${h.id}')">Edit</button></div>`).join('')}<div class="dialog-actions"><button class="primary" onclick="habitForm()">+ Add a habit</button></div>`)}
function habitForm(id){const h=state.habits.find(h=>h.id===id)||{name:'',target:1,badge:'✨',monthly:true};$('#modalBody').innerHTML=`<h2>${id?'Edit':'A new'} little ritual</h2><label for="habitName">Name · up to 10 characters</label><input id="habitName" maxlength="10" value="${esc(h.name)}"><label for="habitTarget">Daily ticks</label><select id="habitTarget">${[1,2,3,4].map(n=>`<option ${h.target===n?'selected':''}>${n}</option>`).join('')}</select><label for="habitBadge">Monthly badge</label><select id="habitBadge">${['✨','💧','🍊','🌱','🌸','☕','🏃','📖','💊','🌙'].map(b=>`<option ${b===h.badge?'selected':''}>${b}</option>`).join('')}</select><label><input type="checkbox" id="monthly" ${h.monthly?'checked':''}> Show completed habit on monthly calendar</label><div class="dialog-actions">${id?'<button class="text-button" id="archiveHabit">Archive habit</button>':''}<button class="primary" id="saveHabit">Save ritual</button></div>`;$('#saveHabit').onclick=()=>{const name=$('#habitName').value.trim();if(!name){$('#habitName').focus();return}const item={id:id||crypto.randomUUID(),name,target:+$('#habitTarget').value,badge:$('#habitBadge').value,monthly:$('#monthly').checked,icon:h.icon||'✧'};if(id)state.habits=state.habits.map(x=>x.id===id?item:x);else state.habits.push(item);save();closeModal();render()};if(id)$('#archiveHabit').onclick=()=>{state.habits=state.habits.filter(x=>x.id!==id);save();closeModal();render();toast('Archived. Previous days are preserved.')}}
function elapsed(){const t=state.timer;return t.base+(t.running?Math.max(0,Date.now()-t.start):0)}
function duration(ms){const s=Math.floor(ms/1000);return `${String(Math.floor(s/3600)).padStart(2,'0')}:${String(Math.floor(s/60)%60).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
function todayMinutes(){return Math.round(state.sessions.filter(s=>s.day===today).reduce((n,s)=>n+s.ms,0)/60000)}
function startFocus(n){if(!state.timer.running&&elapsed()===0)state.timer.goal=n;if(!state.timer.running){state.timer.running=true;state.timer.start=Date.now();state.timer.notified=false;save()}navigate('timer')}
function toggleTimer(){const t=state.timer;if(t.running){t.base=elapsed();t.running=false;t.start=null}else{t.start=Date.now();t.running=true}save();render()}
function stopTimer(){const ms=elapsed();if(ms>=1000)state.sessions.unshift({id:crypto.randomUUID(),day:today,ms,time:new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})});state.timer={running:false,base:0,start:null,goal:20};save();render();if(ms>=1000)toast('A little focus, recorded.')}
function addGoal(n){state.timer.goal+=n;state.timer.notified=false;save();render()}
function renderTimer(){return `<section class="hero"><div><div class="eyebrow">ONE THING AT A TIME</div><h1>A little focus.</h1><p class="subtitle">Find your own rhythm. We’ll keep the time.</p></div></section><div class="timer-layout"><section class="timer-face">${character(false)}<div class="wall-clock" id="wallClock"></div><div class="timer-caption">THE WORLD CAN WAIT A MOMENT</div><div class="timer-progress"><div id="timerBar"></div></div><div class="elapsed" id="elapsed"></div><div class="timer-caption" id="goalCaption">ELAPSED · ${state.timer.goal} MINUTE GOAL</div><div class="timer-actions"><button class="primary" onclick="toggleTimer()">${state.timer.running?'Ⅱ Pause':elapsed()?'↗ Resume':'▷ Begin'}</button><button class="secondary" onclick="stopTimer()">Finish & save</button></div><div class="duration-options">${[20,40,60].map(n=>`<button class="pill" onclick="addGoal(${n})">+${n} min</button>`).join('')}</div><p class="subtitle" style="margin:23px 0 0;font-size:10px">Keeps time while you’re away. No rush to finish.</p></section><section class="card"><div class="eyebrow">TODAY’S LITTLE EFFORTS</div><h2>${todayMinutes()} minutes, well spent.</h2><div>${state.sessions.filter(s=>s.day===today).map(s=>`<div class="session"><div>Focus session<small>${esc(s.time)} · ${Math.round(s.ms/60000)} minutes</small></div><button onclick="editSession('${s.id}')">Edit ↗</button></div>`).join('')||'<p class="empty">A fresh page for your focus.<br>Your finished sessions will appear here.</p>'}</div><p class="gentle-note"><span>✧</span> A few minutes counts, too.</p></section></div>`}
function editSession(id){const s=state.sessions.find(x=>x.id===id);modal(`<h2>Edit your focus time</h2><label for="sessionMinutes">Minutes</label><input id="sessionMinutes" type="number" min="1" max="1440" value="${Math.max(1,Math.round(s.ms/60000))}"><div class="dialog-actions"><button class="text-button" id="deleteSession">Remove session</button><button class="primary" id="saveSession">Save</button></div>`);$('#deleteSession').onclick=()=>{state.sessions=state.sessions.filter(x=>x.id!==id);save();closeModal();render()};$('#saveSession').onclick=()=>{const n=+$('#sessionMinutes').value;if(n<1||n>1440)return;s.ms=n*60000;save();closeModal();render()}}
function updateClock(){if($('#wallClock'))$('#wallClock').textContent=new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'});if($('#elapsed'))$('#elapsed').textContent=duration(elapsed());if($('#timerBar'))$('#timerBar').style.width=Math.min(100,elapsed()/(state.timer.goal*60000)*100)+'%';if(state.timer.running&&elapsed()>=state.timer.goal*60000&&!state.timer.notified){state.timer.notified=true;save();toast('Your goal is reached. Keep going if it feels right.');if('Notification' in window && Notification.permission==='granted')new Notification('A little focus, well spent',{body:'Your goal is reached. Your timer is still running.'})}}
setInterval(updateClock,1000);
function renderDiary(){const start=weekStart(diaryDate),d=parse(diaryDate);return `<section class="hero"><div><div class="eyebrow">YOUR DAYS, IN YOUR OWN WORDS</div><h1>A little to remember.</h1><p class="subtitle">The ordinary moments belong here, too.</p></div></section><div class="diary-toolbar"><div class="week-controls"><button class="arrow" onclick="moveDiary(-1)" aria-label="Previous period">‹</button><span>${diaryView==='week'?`${parse(start).toLocaleDateString('en-GB',{day:'numeric',month:'short'})} — ${parse(shift(start,6)).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'})}`:diaryView==='month'?d.toLocaleDateString('en-GB',{month:'long',year:'numeric'}):fullDate(diaryDate)}</span><button class="arrow" onclick="moveDiary(1)" aria-label="Next period">›</button></div><div class="view-switch">${['day','week','month'].map(v=>`<button class="${diaryView===v?'active':''}" onclick="diaryView='${v}';render()">${v[0].toUpperCase()+v.slice(1)}</button>`).join('')}</div></div>${diaryView==='week'?renderWeek(start):diaryView==='month'?renderMonth():renderDiaryDay()}`}
function renderWeek(start){if(!state.weeks[start])state.weeks[start]=[];return `<div class="diary-layout"><div><div class="zoom"><span>Page zoom</span><input aria-label="Weekly page zoom" type="range" min="40" max="120" value="${zoom*100}" oninput="zoom=+this.value/100;resizePaper()"><span id="zoomValue">${Math.round(zoom*100)}%</span></div><div class="page-scroller"><div id="paperSizer" style="width:${600*zoom}px;height:${1050*zoom}px"><div class="week-paper" id="weekPaper" style="transform:scale(${zoom})"><div class="paper-heading">The little things <span>${parse(start).toLocaleDateString('en-GB',{month:'long',year:'numeric'}).toUpperCase()}</span></div>${Array.from({length:7},(_,i)=>{const k=shift(start,i);return `<div class="week-day" tabindex="0" role="button" aria-label="Edit ${fullDate(k)}" onclick="openEntry('${k}')" onkeydown="if(event.key==='Enter')openEntry('${k}')"><div class="day-title">${parse(k).toLocaleDateString('en-GB',{weekday:'long'})}<span>${parse(k).getDate()} ${k===today?'· TODAY':''}</span></div><div class="day-preview">${esc(day(k).text)||'<span style="color:#b6aa9a">A little room for your day…</span>'}</div></div>`}).join('')}${state.weeks[start].map(s=>`<button class="stamp" data-id="${s.id}" aria-label="${esc(s.art)} stamp. Drag to move; arrow keys to nudge; Delete to remove." style="left:${s.x}px;top:${s.y}px">${esc(s.art)}</button>`).join('')}</div></div></div></div><aside class="card stamp-panel"><div class="eyebrow">MAKE YOUR MARK</div><h2>Little stamps</h2><p>Pick a stamp, then drag it anywhere on your week.</p><div class="stamp-library">${['🌸','✦','🌱','☕','🍊','♡','🌙','🐈'].map(a=>`<button aria-label="Add ${a} stamp" onclick="addStamp('${a}')">${a}</button>`).join('')}</div><p class="stamp-hint">Your curated starter collection.<br><br>Tap a day to write.<br>Select a stamp, then use arrow keys to nudge or Delete to remove.</p><button class="text-button" onclick="removeStamp()">Remove selected stamp</button></aside></div>`}
function resizePaper(){$('#paperSizer').style.width=600*zoom+'px';$('#paperSizer').style.height=1050*zoom+'px';$('#weekPaper').style.transform=`scale(${zoom})`;$('#zoomValue').textContent=Math.round(zoom*100)+'%'}
function addStamp(art){const start=weekStart(diaryDate),list=state.weeks[start]||(state.weeks[start]=[]);list.push({id:crypto.randomUUID(),art,x:450-(list.length%3)*55,y:100+(list.length%7)*140});save();render();toast('Added to your week. Drag it into place.')}
function bindStamps(){$$('.stamp').forEach(el=>{el.onpointerdown=e=>{e.preventDefault();activeStamp=el.dataset.id;el.focus();el.setPointerCapture(e.pointerId);const s=state.weeks[weekStart(diaryDate)].find(s=>s.id===activeStamp),ox=e.clientX,oy=e.clientY,x=s.x,y=s.y;el.onpointermove=ev=>{s.x=Math.max(0,Math.min(542,x+(ev.clientX-ox)/zoom));s.y=Math.max(0,Math.min(992,y+(ev.clientY-oy)/zoom));el.style.left=s.x+'px';el.style.top=s.y+'px'};el.onpointerup=()=>{el.onpointermove=null;save()}};el.onkeydown=e=>{activeStamp=el.dataset.id;if(['Delete','Backspace'].includes(e.key)){e.preventDefault();removeStamp();return}const delta={ArrowLeft:[-5,0],ArrowRight:[5,0],ArrowUp:[0,-5],ArrowDown:[0,5]}[e.key];if(delta){e.preventDefault();const s=state.weeks[weekStart(diaryDate)].find(s=>s.id===activeStamp);s.x=Math.max(0,Math.min(542,s.x+delta[0]));s.y=Math.max(0,Math.min(992,s.y+delta[1]));el.style.left=s.x+'px';el.style.top=s.y+'px';save()}}})}
function removeStamp(){if(!activeStamp){toast('Select a stamp on the page first.');return}const k=weekStart(diaryDate);state.weeks[k]=state.weeks[k].filter(s=>s.id!==activeStamp);activeStamp=null;save();render()}
function moveDiary(n){if(diaryView==='month'){const d=parse(diaryDate);d.setDate(1);d.setMonth(d.getMonth()+n);diaryDate=key(d)}else diaryDate=shift(diaryDate,n*(diaryView==='week'?7:1));render()}
function badges(k){const d=day(k),hs=habitsFor(k);return [...new Set([...hs.filter(h=>h.monthly&&(d.ticks[h.id]||0)>=h.target).map(h=>h.badge),...d.badges])]}
function renderMonth(){const d=parse(diaryDate),first=new Date(d.getFullYear(),d.getMonth(),1),offset=(first.getDay()+6)%7,days=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();return `<section class="card month-card"><div class="month-grid">${['MON','TUE','WED','THU','FRI','SAT','SUN'].map(v=>`<div class="weekday">${v}</div>`).join('')}${Array.from({length:offset},()=>'<div class="month-cell blank"></div>').join('')}${Array.from({length:days},(_,i)=>{const k=key(new Date(d.getFullYear(),d.getMonth(),i+1));return `<div class="month-cell ${k===today?'today':''}" role="button" tabindex="0" aria-label="${fullDate(k)} badges" onclick="badgeDialog('${k}')" onkeydown="if(event.key==='Enter')badgeDialog('${k}')"><span class="num">${i+1}</span>${day(k).text?'<span class="entry-dot"></span>':''}<div class="badges">${badges(k).map(esc).join(' ')}</div></div>`}).join('')}</div><p class="monthly-note">Tap a day to add a badge. Completed rituals appear here automatically, unless hidden in habit settings.</p></section>`}
function badgeDialog(k){modal(`<div class="eyebrow">${esc(fullDate(k))}</div><h2>A little mark for today</h2><p class="subtitle">Tap to add or remove a manual badge. Automatic habit badges are managed in Edit habits.</p><div class="choices">${['🌱','🏃','💧','✨','🌸','☕','🍊','📖','🌙','♡'].map(b=>`<button class="choice ${day(k).badges.includes(b)?'selected':''}" onclick="toggleBadge('${k}','${b}',this)">${b}</button>`).join('')}</div><div class="dialog-actions"><button class="text-button" onclick="closeModal();openEntry('${k}')">Read / edit diary</button><button class="primary" onclick="closeModal();render()">Done</button></div>`)}
function toggleBadge(k,b,el){const d=day(k);d.badges=d.badges.includes(b)?d.badges.filter(x=>x!==b):[...d.badges,b];el.classList.toggle('selected',d.badges.includes(b));save()}
function renderDiaryDay(){return `<section class="card"><div class="card-head"><h2>${parse(diaryDate).toLocaleDateString('en-GB',{weekday:'long'})}</h2><button class="text-button" onclick="openEntry('${diaryDate}')">Edit entry ↗</button></div><p style="white-space:pre-wrap;line-height:2;min-height:160px">${esc(day(diaryDate).text)||'<span class="subtitle">Your day is yours to write.</span>'}</p><div>${badges(diaryDate).map(esc).join(' ')}</div></section>`}
function settings(){modal(`<div class="eyebrow">A SPACE THAT FEELS LIKE YOU</div><h2>Make it yours.</h2><label>Choose your mood</label><div class="choices"><button class="choice ${state.theme==='playful'?'selected':''}" onclick="setTheme('playful')">✿ Playful</button><button class="choice ${state.theme==='elegant'?'selected':''}" onclick="setTheme('elegant')">◯ Elegant</button></div><label>Your colours</label><div class="choices"><button class="choice ${state.color==='rose'?'selected':''}" onclick="state.color='rose';save();render();settingsRefresh()">◉ Warm rose</button><button class="choice ${state.color==='sage'?'selected':''}" onclick="state.color='sage';save();render();settingsRefresh()">◉ Soft sage</button></div><div class="setting-row"><span>Focus section on My day</span><input aria-label="Show focus section" type="checkbox" ${state.showFocus?'checked':''} onchange="state.showFocus=this.checked;save();render()"></div><div class="setting-row"><span>Your little companion</span><button class="text-button" onclick="iconDialog()">Choose ↗</button></div><div class="setting-row"><span>Keep a copy of your days</span><button class="text-button" onclick="exportData()">Export backup ↓</button></div><p class="subtitle" style="margin-top:20px;font-size:10px">Clickable prototype · Your entries are saved in this browser. Accounts, cross-device sync and cloud backup are not connected yet. Starter stamps are placeholders for the artist’s collection.</p>`)}
function settingsRefresh(){closeModal();settings()}function setTheme(t){state.theme=t;save();render();settingsRefresh()}
function iconDialog(){if($('#modal').open)closeModal();modal(`<h2>Your little companion</h2><p class="subtitle">A familiar face for your everyday.</p><div class="choices">${[['cat','🐈','Cat'],['flower','✿','Flower'],['moon','☾','Moon']].map(([id,icon,name])=>`<button class="choice ${state.icon===id?'selected':''}" onclick="state.icon='${id}';save();closeModal();render()">${icon} ${name}</button>`).join('')}</div>`)}
function exportData(){const blob=new Blob([JSON.stringify({app:'Little Days',version:1,exportedAt:new Date().toISOString(),data:state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`little-days-${today}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('A copy of your days, for safekeeping.')}
$('#settings').onclick=settings;$('#mobileSettings').onclick=settings;$('#themeShortcut').onclick=settings;
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(['today','timer','diary'].includes(p)&&page!==p){page=p;render()}});
if(['today','timer','diary'].includes(location.hash.slice(1)))page=location.hash.slice(1);render();
if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});
